# Let me try hypothesis: keep only colors that appear in 3+ quadrants
# (excluding 4-counters if any, but none except 5 which is background)

grid = [
    [5, 5, 9, 5, 5, 0, 5, 5, 7, 9, 9, 9],
    [9, 9, 9, 5, 5, 0, 5, 7, 5, 9, 9, 5],
    [5, 5, 5, 5, 0, 0, 7, 7, 5, 9, 5, 5],
    [5, 5, 5, 5, 0, 0, 5, 5, 0, 5, 7, 5],
    [5, 0, 5, 5, 0, 0, 5, 5, 5, 5, 5, 5],
    [0, 5, 0, 0, 5, 0, 5, 5, 5, 5, 5, 5],
    [7, 5, 5, 5, 5, 5, 5, 9, 9, 5, 5, 5],
    [5, 5, 7, 5, 1, 1, 9, 9, 5, 1, 1, 5],
    [5, 5, 5, 5, 5, 1, 9, 9, 5, 1, 1, 1],
    [5, 5, 7, 0, 0, 0, 5, 3, 3, 1, 5, 1],
    [5, 5, 7, 0, 0, 5, 5, 5, 3, 1, 1, 1],
    [5, 5, 5, 0, 5, 0, 3, 3, 3, 1, 1, 1]
]

def count_colors_in_quadrants(grid):
    quadrants = {
        'TL': set(), 'TR': set(), 'BL': set(), 'BR': set()
    }
    for r in range(12):
        for c in range(12):
            color = grid[r][c]
            if color == 5:
                continue  # skip background
            if r < 6 and c < 6:
                quadrants['TL'].add(color)
            elif r < 6 and c >= 6:
                quadrants['TR'].add(color)
            elif r >= 6 and c < 6:
                quadrants['BL'].add(color)
            else:
                quadrants['BR'].add(color)
    return quadrants

quads = count_colors_in_quadrants(grid)
print("Colors in each quad (non-5):")
for name, colors in sorted(quads.items()):
    print(f"  {name}: {sorted(colors)}")

# Now find colors in >= 3 quadrants
all_colors = set()
for colors in quads.values():
    all_colors.update(colors)

counts = {}
for color in all_colors:
    match_count = sum(1 for cs in quads.values() if color in cs)
    counts[color] = match_count

print("\nColors in 3+ quadrants:")
for color, cnt in sorted(counts.items(), key=lambda x: -x[1]):
    print(f"  {color}: {cnt} quads")

